  ui_story_5081_50810100_90_dialog_content = "(สถานที่ที่น่าจะเป็นที่สุดคืออัมบราตัน ซึ่งเป็นเมืองสรรพสิ่งบันเทิงของแอสตรา!)",
  ui_story_5081_50810100_91_dialog_content = "เทคนิคที่ทันสมัยที่สร้างความประทับใจให้ทั่วโลก! ผลงานอันยอดเยี่ยมจากผู้อำนวยการใหม่ของโรงละครสวีทดรีมส์จะถูกเปิดเผยคืนนี้!",
