  ui_story_5081_50810301_82_dialog_content = "ยังไงก็ตาม, สิ่งหนึ่งนำไปสู่อีกสิ่งหนึ่ง, และตอนนี้เราทั้งสองก็ทำงานที่นี่...",
  ui_story_5081_50810301_83_dialog_content = "เมื่อไม่ยุ่ง เรายังสามารถเล่นเกมกระดานกับกลุ่มลูกค้าของเราได้เลย",
  ui_story_5081_50810301_84_dialog_content = "คนสามารถหลงไหลได้อย่างสมบูรณ์ในเกมกลยุทธ์ที่นี่—นี่ไม่ใช่สิ่งที่คุณจะพบได้ในสถานที่ส่วนใหญ่...",
  ui_story_5081_50810301_85_dialog_content = "แม้ว่าเกมส์เจรจาจะดีกว่าเยอะ จิ๊บ!",
  ui_story_5081_50810301_86_dialog_content = "งั้นสองคนนั้นก็ติดอยู่กับเกมที่นี่เหมือนกันเหรอห้ะ?",
  ui_story_5081_50810301_87_dialog_content = "ที่นี่มีบางอย่างที่พิเศษจริง ๆ... แต่ทำไมฉันถึงไม่เห็นเจ้าของร้านอยู่ที่ไหนเลยนะ?",
  ui_story_5081_50810301_88_dialog_content = "\"B\" มีเชื้อสายกึ่งมนุษย์ที่หายากเหมือนกับเรา ไม่ง่ายสำหรับเธอที่จะออกมาในเวลากลางวัน",
  ui_story_5081_50810301_89_dialog_content = "เธอต้องเผชิญกับปัญหามากมายในอดีตเพราะเป็นสายเลือดของตระกูลนั้นด้วย ดังนั้น ขอร้องนะ...",
