  ui_story_5081_50810301_92_dialog_content = "ฉันแค่มีอะไรจะถามเธอเท่านั้น คุณอยากจะส่งข้อความให้เธอไหม?",
  ui_story_5081_50810301_93_dialog_content = "แน่นอน, PlayerName.",
  ui_story_5081_50810301_94_dialog_content = "ให้ฉันจบเกมนี้ก่อน... อืม, หมายถึงการจัดการกับกลุ่มลูกค้านี้ แล้วฉันจะทำตามทันที",
  ui_story_5081_50810301_95_dialog_content = "ได้สิ",
  ui_story_5081_50810301_96_dialog_content = "หา? ว่าแต่โอดีกับโจมูหายไปไหนนะ...",
  ui_story_5081_50810301_97_dialog_content = "คุณหยอกฉันหรือ? ฉันคิดแผนการใหม่ๆมาเพียบเพื่อที่จะได้รับเกมของฉันเองนะ!",
  ui_story_5081_50810301_98_dialog_content = "ดูสิ ฉันยังปรับแต่งตัวควบคุมของฉันเอง... ลองมาดูถ้าคุณต้องการ!",
