  ui_story_5081_50810301_111_dialog_content = "<color=#e8d9bb>ภาพที่มีรายละเอียดละเอียด ร่วมกับการนำเสนอที่คุณภาพและเอฟเฟกต์เสียงพิเศษ สร้างประสบการณ์ที่น่าจดจำ</color>",
  ui_story_5081_50810301_112_dialog_content = "นี่คือวิธีที่ฉันควรจะเข้าโค้งหรือเปล่า? ฉันเข้าใจมากแล้วตอนนี้!",
  ui_story_5081_50810301_113_dialog_content = "ฉันสะสมลูมินาทุกครั้งที่ฉันลอยรอบมุม ดังนั้นฉันควรยิงมันที่อิคลิพไซท์หรือไม่? คิดว่าฉันควรลองทำดู!",
  ui_story_5081_50810301_114_dialog_content = "รอสักครู่... อิคลิพไซท์ตัวนี้แข็งแกร่งเกินไปไม่ใช่เหรอ?",
