  ui_story_5081_50810302_22_dialog_content = "<color=#e8d9bb>แต่ในที่สุด ห้องเกมส์ก็ระเบิดเป็นเสียงปรบมือที่กระตุ้นเต็มที่เมื่อการแข่งขันสิ้นสุดลงอย่างตื่นเต้นและสำเร็จ</color>",
  ui_story_5081_50810302_23_dialog_content = "ว้าว!",
  ui_story_5081_50810302_24_dialog_content = "มือใหม่เคลียร์ Tempest Gorge ได้ในครั้งแรกเลยหรือ? มันจะเป็นไปได้ยังไงนะ?",
