  ui_story_5081_50810302_29_dialog_content = "เมื่อฉันกำลังต่อสู้เพื่อผ่านเลนที่เป็นวงเล็บเหล็ก, เธอก็นั่งอยู่ข้าง ๆ... หืม?",
