  ui_story_5081_50810602_64_dialog_content = "เข้าใจ",
  ui_story_5081_50810602_65_dialog_content = "นั่นเป็นเหตุผลว่าทำไมทหารอิลลูมินา<color=#FFB400>ปรับตัวเอง</color>ให้เหมาะสมกับ<color=#FFB400>พลังรบ</color>ของอาวุธของพวกเขา... ทุกอย่างเป็นที่เข้าใจแล้ว!",
  ui_story_5081_50810602_66_dialog_content = "เกมแน่นอนสามารถนำมาใช้สำหรับการฝึกฝน... หรืออีกนัยหนึ่ง การฝึกฝนก็สามารถถือว่าเป็นเกมประเภทหนึ่ง!",
  ui_story_5081_50810602_67_dialog_content = "ประสบการณ์นี้ทั้งน่าประหลาดใจและเปิดโลก!",
  ui_story_5081_50810602_68_dialog_content = "ขอบคุณนะ บาเทีย! ถ้าฉันกลับมาท้าทายคุณในอนาคต จะเป็นไปได้ไหมคะ?",
  ui_story_5081_50810602_69_dialog_content = "?",
  ui_story_5081_50810602_70_dialog_content = "น-นั่นแล้วแต่... ด-คุณมี...",
  ui_story_5081_50810602_71_dialog_content = "หืมม?",
  ui_story_5081_50810602_72_dialog_content = "ฉันคิดว่าเธอต้องการถามว่าคุณสนุกไหมเมื่อกี้ และคุณชอบเล่นเกมนั้นหรือไม่",
  ui_story_5081_50810602_73_dialog_content = "แน่นอน! มันเป็นประสบการณ์ที่ตื่นเต้นมาก! ฉันไม่รู้เลยว่าวิดีโอเกมสามารถสนุกขนาดนี้!",
  ui_story_5081_50810602_74_dialog_content = "และมีบางสิ่งบอกฉันว่าฉันจะได้รับประสบการณ์มากขึ้นถ้าฉันยังคงเล่นเกมเหล่านั้น!",
  ui_story_5081_50810602_75_dialog_content = "ในการพยายามนี้ ฉันจะไม่สะดุดเด็ดขาด!",
  ui_story_5081_50810602_76_dialog_content = "ถ้างั้น... ช่วยรับนี่ไปเถอะ",
  ui_story_5081_50810602_77_dialog_content = "เธอผ่าน! น-นี่ไม่ได้เลย! เธอไม่รู้ว่าเกมนั้นมีค่าเท่าไหร่...",
  ui_story_5081_50810602_78_dialog_content = "คุณแนะนำเกมนี้ให้ฉันหรือไม่? ดีมากเลย! ฉันจะแน่นอนฝึกฝนตลอดวันและคืนเมื่อได้รับสำเนาของฉัน!",
  ui_story_5081_50810602_79_dialog_content = "ฉันรอคอยการดวลครั้งต่อไปของเรา!",
  ui_story_5081_50810602_80_dialog_content = "อืม... ค-ค-ครับ!",
  ui_story_5081_50810602_81_dialog_content = "และเมื่อฉันเรียนรู้ความลับของการฝึกฝนเกมวิดีโอของอิลลูมินาได้...",
  ui_story_5081_50810602_82_dialog_content = "ฉันอาจมีโอกาสที่จะได้ชดใช้ความพ่ายแพ้ของฉันต่ออิงเกลในที่สุด!",
  ui_story_5081_50810602_83_dialog_content = "อิงเกล?",
  ui_story_5081_50810602_84_dialog_content = "เจ้าหน้าที่ข่าวกรองในสหพันธรัฐอิลลูมินา ใช่ค่ะ",
  ui_story_5081_50810602_85_dialog_content = "ตามการพ่ายแพ้ของฉันที่มือของเธอในการฝึกซ้อมทางทหารร่วมกัน ฉันมักจะคิดถึงวิธีที่ดีที่สุดในการชิงชัยชนะจากเธอ",
  ui_story_5081_50810602_86_dialog_content = "ฉันยังบังเอิญเจอเธอระหว่างทางมาที่นี่นะ!",
  ui_story_5081_50810602_87_dialog_content = "แต่เธอยุ่งยากจนไม่สังเกตเห็นฉัน...",
  ui_story_5081_50810602_88_dialog_content = "เธอ...",
  ui_story_5081_50810602_89_dialog_content = "!",
  ui_story_5081_50810602_90_dialog_content = "หืม? นั่นไม่ใช่เจ้าหน้าที่ข่าวกรอง Yingel หรือเปล่า?",
  ui_story_5081_50810602_91_dialog_content = "...",
  ui_story_5081_50810602_92_dialog_content = "คงไม่ใช่ฉันคนเดียวที่ถูกเพิกเฉยนะ",
  ui_story_5081_50810602_93_dialog_content = "เป็นอะไรไปล่ะ",
  ui_story_5081_50810602_94_dialog_content = "อ๋อ, ไม่มีอะไรครับ",
  ui_story_5081_50810602_95_dialog_content = "(เจ้าหน้าที่ข่าวกรองระดับสูงจากอิลลูมินาทำอะไรอยู่ในอัมบราตันนี่? เธอจะไม่ไปตามหากรอนรูด้วยหรือ?)",
  ui_story_5081_50810602_96_dialog_content = "ถ้าเธอเห็นเธอนั้น ก็บอกให้เธอรู้เถอะว่าฉันกำลังจะท้าทายเธอ!",
  ui_story_5081_50810602_97_dialog_content = "ว-จะทำ.",
  ui_story_5081_50810602_98_dialog_content = "เกมแฟนตาซี—แหล่งรายได้ที่ดีที่สุดของฉันเลย! ฉันทำได้... ฉันสมควรกับมันแล้ว! ว้าว!",
  ui_story_5081_50810602_99_dialog_content = "คุณยังคงพูดถึงเรื่องนั้นอยู่เหรอ โจมู? ... ห๊ะ? ทำไมคุณถึงนอนอยู่บนพื้นล่ะ?",
  ui_story_5081_50810602_100_dialog_content = "ฉันทำได้... ฉันผ่าน... อื้อ...",
  ui_story_5081_50810602_101_dialog_content = "ดูเหมือนว่าเขาเมาเครื่องเล็กน้อยจากการเล่นนานเกินไป... ฉันรู้อยู่แล้วว่าเขาไม่เหมาะสมกับเกมประเภทนี้!",
  ui_story_5081_50810602_102_dialog_content = "ถ้าฉันรู้ว่าเขายินยอมเสี่ยงชีวิตเพื่อเงิน ฉันคงไม่เอาเขามาด้วย",
  ui_story_5081_50810602_103_dialog_content = "แม้ว่าเขาจะไม่เคยหยุดพูดเรื่องการทำเงิน แต่เมื่อฉันเห็นเขาเล่นก่อนหน้านี้...",
  ui_story_5081_50810602_104_dialog_content = "ดูเหมือนว่าโจมูสนุกมากนะ ใช่ไหม?",
  ui_story_5081_50810602_105_dialog_content = "... ฉันเกือบจะหลอก \"B\" ได้แล้ว... นี่คือความเสียดาย...",
  ui_story_5081_50810602_106_dialog_content = "(แม้แต่พ่อค้าที่หาเงินอย่างโจมูยังสามารถติดเกมวิดีโอได้ น่าจะเป็นเพราะความน่าสนใจของเกมที่ทรงพลังเลยทีเดียว)",
  ui_story_5081_50810602_107_dialog_content = "หัวฉันหมุน... น้ำ... ฉันต้องการน้ำ...",
  ui_story_5081_50810602_108_dialog_content = "รอก่อนนะ ฉันจะไปหาเครื่องดื่มให้คุณและโอดี หลังจากที่พูดคุยมาทั้งหมดนี้ ฉันแน่ใจว่าเธอก็คงจะกระหายน้ำเหมือนกัน",
  ui_story_5081_50810602_109_dialog_content = "คิดว่านี่เป็นของขวัญขอบคุณที่พาฉันมาที่นี่วันนี้นะ",
  ui_story_5081_50810602_110_dialog_content = "เดี๋ยวฉันจะรีบกลับมานะ!",
  ui_story_5081_50810701_1_dialog_content = "<color=#e8d9bb>ปัง—</color>",
  ui_story_5081_50810701_2_dialog_content = "มันเป็นฉันรึเปล่า หรือว่าเครื่องเหล่านี้ดูเหมือนว่ามาจาก Illumina จริงๆนะ?",
  ui_story_5081_50810701_3_dialog_content = "ฉันสงสัยว่าโจมูกับโอดีอยากดื่มอะไรนะ?",
  ui_story_5081_50810701_4_dialog_content = "อาจจะเป็น \"คลาสสิกและเข้าถึงได้ง่าย\" หรือเปล่า?",
  ui_story_5081_50810701_5_dialog_content = "<color=#e8d9bb>ปัง—</color>",
  ui_story_5081_50810701_6_dialog_content = "...",
  ui_story_5081_50810701_7_dialog_content = "ฉันรู้ว่ามีคนกำลังมองฉัน",
  ui_story_5081_50810701_8_dialog_content = "ใครน่ะ?",
  ui_story_5081_50810701_9_dialog_content = "อ๊ะ! ข... ขอโทษค่ะ!",
  ui_story_5081_50810701_10_dialog_content = "หือ? เธอเองเหรอ บาเทีย",
  ui_story_5081_50810701_11_dialog_content = "ขอโทษที่ตะโกนเมื่อกี้นะ ฉันคิดว่ามีคนพยายามขโมยเหรียญของฉันหรืออะไรทำนองนั้น",
  ui_story_5081_50810701_12_dialog_content = "ฉัน-คือว่า... ง-งั้นเหรอ...",
  ui_story_5081_50810701_13_dialog_content = "ว้าว! นั่น...ไอศกรีมเหรอ? แต่ทำไมคุณไม่กินล่ะ? ดูเหมือนว่ามันกำลังจะละลายนะ!",
  ui_story_5081_50810701_14_dialog_content = "ฉ-ฉันมีสิ่งนี้ให้คุณ...",
  ui_story_5081_50810701_15_dialog_content = "รอสักครู่... คุณซื้อสิ่งนี้มาเพื่อฉันเหรอ?",
  ui_story_5081_50810701_16_dialog_content = "ช่าย",
  ui_story_5081_50810701_17_dialog_content = "แล้วผมควรรีบกินเถอะ! ขอบคุณที่ยังไม่ละลายหมด...",
  ui_story_5081_50810701_18_dialog_content = "ฉันไม่แน่ใจว่ามันยังสามารถเรียกว่า \"ไอศกรีม\" ได้หรือไม่นะ",
  ui_story_5081_50810701_19_dialog_content = "แต่ไม่เป็นไรนะ! เราสามารถซื้อเพิ่มเติมได้เสมอ! นอกจากนี้ มันยังกินได้ดีอยู่ เฮ้ย, มันเย็นจัง!",
  ui_story_5081_50810701_20_dialog_content = "จริงหรือ? ฉันดีใจมากที่คุณชอบนะ",
  ui_story_5081_50810701_21_dialog_content = "แล้วก็... ฉันอยากจะขอบคุณคุณ",
  ui_story_5081_50810701_22_dialog_content = "สำหรับการร่วมทีมกับฉัน... และช่วยฉันจัดการกับผู้ท้าทายที่กระตือรือร้นเกินไป.",
  ui_story_5081_50810701_23_dialog_content = "ฉันควรจะเป็นคนขอบคุณคุณ! ฉันคงไม่มีทางรอดได้ถ้าไม่มีความช่วยเหลือจากคุณ",
  ui_story_5081_50810701_24_dialog_content = "และเนื่องจากคุณใจดีพอที่จะนำไอศกรีมมาให้ฉัน ทำไมฉันจึงไม่เลี้ยงคุณด้วยเครื่องดื่มล่ะ? น้ำผลไม้หรือกาแฟ?",
  ui_story_5081_50810701_25_dialog_content = "เอิ่ม... น-น้ำมะเขือเทศ ของนี้... ครับ/ค่ะ...",
  ui_story_5081_50810701_26_dialog_content = "ได้เลย!",
  ui_story_5081_50810701_27_dialog_content = "<color=#e8d9bb>ปัง—</color>",
  ui_story_5081_50810701_28_dialog_content = "รับนี่ไป! ดังนั้นคุณชอบดื่มแบบนี้ใช่มั้ยล่ะ",
  ui_story_5081_50810701_29_dialog_content = "อาฮะ... ฉันไม่ค่อยออกไปข้างนอกในช่วงกลางวัน ดังนั้นฉันต้องพึ่งอาหารแบบนี้เพื่อความสมบูรณ์... และมันก็ใช้ได้ดีเหมือนกันนะ",
  ui_story_5081_50810701_30_dialog_content = "เอ่อ, ขอโทษที่ถามนะ... แต่มันมีอะไรเกี่ยวกับการเป็นค้างคาวบ้างรึเปล่า?",
  ui_story_5081_50810701_31_dialog_content = "มันก็เป็นอย่างนั้น... ซึ่งเป็นเหตุผลว่าทำไมการออกไปข้างนอกถึงเป็นปัญหาสำหรับฉัน",
  ui_story_5081_50810701_32_dialog_content = "การมีปฏิสัมพันธ์กับคนอื่น... สำหรับฉันก็ไม่ง่ายเหมือนกันน่ะค่ะ",
  ui_story_5081_50810701_33_dialog_content = "ฉันเป็นออโรเรียนเหมือนคนอื่น ๆ... แต่ก็ไม่ได้เต็มที่",
  ui_story_5081_50810701_34_dialog_content = "มีหลายสิ่งที่คนอื่นทำได้... ที่ฉันไม่เคยทำได้เลย",
  ui_story_5081_50810701_35_dialog_content = "นั่นหรือเหตุผลที่คุณอยู่ในบ้านและเล่นเกมจนกว่าจะเป็นที่สุดในนั้นเหรอครับ?",
  ui_story_5081_50810701_36_dialog_content = "อ-อายนะ?",
  ui_story_5081_50810701_37_dialog_content = "แน่นอนว่าไม่! ในความเป็นจริง มันเป็นความสำเร็จที่น่าเหลือเชื่อ!",
  ui_story_5081_50810701_38_dialog_content = "การเป็นผู้เล่นที่ยอดเยี่ยมที่สุดในเกมเดียวนั้นถือเป็นความสำเร็จที่น่าประทับใจสำหรับเกมเมอร์ใด ๆ",
  ui_story_5081_50810701_39_dialog_content = "แต่ชื่อของคุณอยู่ที่ด้านบนของ leaderboard ทุกอันที่นี่ - หรือแม้กระทั่งทั่วทั้ง Astra!",
  ui_story_5081_50810701_40_dialog_content = "\"B\" นั้นเป็นฮีโร่และสัญลักษณ์ในตัวเธอเองแล้ว—อาจจะเป็นตำนานเลยก็ได้! เมื่อฉันมาที่ร้านนี้...",
  ui_story_5081_50810701_41_dialog_content = "ฉันทำมันด้วยเจตนาที่จะขยายขอบเขตของตัวฉันเองด้วย!",
  ui_story_5081_50810701_42_dialog_content = "...",
  ui_story_5081_50810701_43_dialog_content = "แต่...แต่คุณไม่ได้มาที่นี่ด้วยเจตนาที่จะมาเล่นเกมส์นะ",
  ui_story_5081_50810701_44_dialog_content = "ฮ่าๆ นั่นแหละ! เมื่อฉันปรากฏตัวครั้งแรก ฉันมีเป้าหมายชัดเจน—คือการค้นหาเพื่อนที่หายไปของฉัน กรอนรู",
  ui_story_5081_50810701_45_dialog_content = "คุณเห็นด้วยนะ เธอคือคนที่แนะนำเกมหลายๆ เกมให้ฉันรู้จัก",
  ui_story_5081_50810701_46_dialog_content = "ส่วนใหญ่ ฉันรับมันไว้เพราะเธอให้มันมาให้ฉัน",
  ui_story_5081_50810701_47_dialog_content = "และฉันจะเล่นพวกมันเพราะมันมาจากเพื่อนเท่านั้น",
  ui_story_5081_50810701_48_dialog_content = "นั่นเป็นเหตุผลว่าทำไมฉันไม่เคยคิดว่าฉันจะชอบห้องเกมมากขนาดนี้ในปัจจุบัน",
  ui_story_5081_50810701_49_dialog_content = "เมื่อฉันคิดถึงการแข่งขันทั้งหมดที่เราเล่นวันนี้...",
  ui_story_5081_50810701_50_dialog_content = "ฉันรู้สึกว่าฉันได้สนุกมากแค่ไหนที่นี่แล้ว",
  ui_story_5081_50810701_51_dialog_content = "อืม... ฉันเข้าใจ.",
  ui_story_5081_50810701_52_dialog_content = "คุณจริง ๆ แล้วสามารถสนุกกับวิดีโอเกมได้นะ",
  ui_story_5081_50810701_53_dialog_content = "ฉันไม่รู้ว่าเป็นเพราะประวัติศาสตร์ของฉัน, เป้าหมาย, หรืออาจเป็นเพราะความรับผิดชอบบางอย่างที่ฉันกำลังรับใส่...",
  ui_story_5081_50810701_54_dialog_content = "แต่... มันยากสำหรับฉันที่จะยอมรับว่าฉันชอบสิ่งประเภทนี้เล็กน้อย",
  ui_story_5081_50810701_55_dialog_content = "ดังนั้นการสามารถเล่นวิดีโอเกมแบบนี้ โดยไม่ต้องกลัวการตัดสินใจ ช่วยให้ฉันสามารถเผชิญหน้ากับความขัดแย้งภายในได้ตรงๆ...",
  ui_story_5081_50810701_56_dialog_content = "ถ้าฉันสามารถสนุกกับเกมอย่างบริสุทธิ์เหมือนคุณและกรอนรู ฉันเดาว่าเราจะสามารถเข้าใจกันมากขึ้นอีก",
  ui_story_5081_50810701_57_dialog_content = "<size=30>กรอนรู... ฉันแอบอิจฉาจริง ๆ ที่เธอมีเพื่อนอย่างคุณ...</size>",
