  ui_story_5081_50811102_52_dialog_content = "ค-ความคิดเห็นของคุณเกี่ยวกับฉันเหรอ?",
  ui_story_5081_50811102_53_dialog_content = "ไม่, นั่นไม่ถูก... คุณกำลังพูดถึงผู้ท้าทายที่รู้จักกันในชื่อ \"Y,\" แต่ว่า...",
  ui_story_5081_50811102_54_dialog_content = "คู่ต่อสู้ของคุณตอนนี้คือเจ้าหน้าที่ข่าวกรอง อิงเกล โปรดอย่าให้ฉันอยู่ในระดับเดียวกับผู้ท้าทายคนล่าสุดนั้น",
  ui_story_5081_50811102_55_dialog_content = "ตอนนี้ที่ Batia ได้ยอมรับทักษะของ อิงเกล แล้ว ฉันคิดว่าฉันควรถามตอนนี้ก็ปลอดภัย",
  ui_story_5081_50811102_56_dialog_content = "กรอนรูกำลังซ่อนตัวอยู่ที่นี่จริงๆ ใช่ไหมเนี่ย?",
  ui_story_5081_50811102_57_dialog_content = "โอ... ฉันขอโทษจริง ๆ นะ กรอนรู...",
  ui_story_5081_50811102_58_dialog_content = "ใช่... นั่นคือความจริง.",
  ui_story_5081_50811102_59_dialog_content = "ถ้ามันเป็นแค่คุณสองคน...",
  ui_story_5081_50811102_60_dialog_content = "ฉันแน่ใจว่าเธอจะไม่รังเกียจที่จะไปพบกับคุณ ทางนี้ค่ะ",
