  ui_story_5081_50811201_2_dialog_content = "ไม่เคยคิดเลยว่าจะมีอุโมงค์อยู่ใต้ที่นี้",
  ui_story_5081_50811201_3_dialog_content = "รายงานข่าวกรองของฉันไม่ได้กล่าวถึงทางลับเลย...",
  ui_story_5081_50811201_4_dialog_content = "กรอนรูได้ลำบากมากในการปกปิดที่นี่ มันเป็นเรื่องที่เข้าใจได้ว่าคุณไม่รู้เรื่องนี้...",
  ui_story_5081_50811201_5_dialog_content = "เรามาถึงแล้ว... ยินดีต้อนรับสู่สตูดิโอใต้ดินของกรอนรูนะครับ.",
  ui_story_5081_50811201_6_dialog_content = "นี่คือพื้นที่ส่วนตัวของเธอที่เธอสามารถวิเคราะห์และฟื้นฟูเกมที่ขุดค้นมาใหม่จากวัฒนธรรมโบราณ",
