  ui_story_5081_50811201_8_dialog_content = "คุณถูกต้องที่คาดว่า กรอนรู อยู่ที่นี่ตลอดเวลา PlayerName... แต่ด้วยเหตุผลที่แตกต่างกัน.",
  ui_story_5081_50811201_9_dialog_content = "เธอไม่ได้มาที่นี่เพื่อซื้อเกมแฟนตาซีที่อยู่ในระหว่างการขายล่วงหน้า เพราะเธอเองคือคนที่ฟื้นฟูมันขึ้นมาในตอนแรก",
  ui_story_5081_50811201_10_dialog_content = "ยกตัวอย่างคือ...",
  ui_story_5081_50811201_11_dialog_content = "เธอคือเจ้าของจริงของ Hidden Fangs, นักเล่นเกมที่มีประสบการณ์และสนับสนุนฉันในการบริหารรันนิ่งนี้",
  ui_story_5081_50811201_12_dialog_content = "ดังนั้นรายงานข่าวกรองของฉันถูกต้อง—นี่จริง ๆ แหละคือฐานลับของเธอ",
  ui_story_5081_50811201_13_dialog_content = "เธอหลีกเลี่ยงหน้าที่สำคัญของตัวเองในฐานะทหารอิลลูมินาเพื่อซ่อมเกมวิดีโอเก่า...",
  ui_story_5081_50811201_14_dialog_content = "ฉันไม่สามารถคิดถึงสิ่งที่เหนือกว่านี้! อิลลูมินากำลังอยู่ในระหว่าง—",
  ui_story_5081_50811201_15_dialog_content = "กลางของอะไร?",
  ui_story_5081_50811201_16_dialog_content = "พักสักหน่อยสิ Yingel ถ้า PlayerName ไม่ได้รับความโปรดปรานจาก Batia คงต้องใช้เวลาอีกปีเพื่อหาที่นี่!",
  ui_story_5081_50811201_17_dialog_content = "ได้รับความโปรดปรานจากฉันหรือ? เขายังไม่ได้มาใกล้ครึ่งทางในการทำเช่นนั้นเลย...",
  ui_story_5081_50811201_18_dialog_content = "รอสักครู่! ฉันไม่ใช่ NPC หรืออะไรทำนองนั้น... กรุณาอย่ามาล้อเล่นแบบนั้น กรอนรู!",
  ui_story_5081_50811201_19_dialog_content = "มันเป็นเพียง... พวกเขาดูเหมือนจะมีเรื่องสำคัญมาก ๆ ที่จะบอกคุณ ดังนั้นฉันจึงพาพวกเขามาที่นี่",
  ui_story_5081_50811201_20_dialog_content = "ยังไงพวกเขาก็เป็นเพื่อนและเพื่อนร่วมงานของคุณ...",
  ui_story_5081_50811201_21_dialog_content = "นั่นไม่ได้หมายความว่าอะไรเลย! ฉันบอกให้ไม่ให้ใครเข้ามาที่นี่จนกว่าวันหยุดพักผ่อนของฉันจะจบไปแล้วไม่ใช่เหรอ?",
  ui_story_5081_50811201_22_dialog_content = "... แต่-แต่คุณกล่าวว่า \"ยกเว้นผู้เล่นที่น่าสนใจเป็นพิเศษ\"...",
  ui_story_5081_50811201_23_dialog_content = "\"ผู้เล่นที่น่าสนใจเป็นพิเศษ\"? คุณไม่ได้พูดถึง PlayerName และอิงเกลใช่ไหม?",
  ui_story_5081_50811201_24_dialog_content = "คุณจริง ๆ คิดว่าทั้งสองคนนั้นจะมีโอกาสต่อสู้กับผู้วางแผนลับข้างหลังฟันที่ซ่อนอยู่ได้หรือไม่?",
  ui_story_5081_50811201_25_dialog_content = "<color=#e8d9bb>ครืนนน...</color>",
  ui_story_5081_50811201_26_dialog_content = "เราถูกดูถูกความสามารถนี่แหละ PlayerName",
  ui_story_5081_50811201_27_dialog_content = "เออ... แต่เราไม่ได้มาที่นี่เพื่อท้าทาย \"ผู้บริหารลับ\" ใด ๆ ในที่แรกเลย!",
  ui_story_5081_50811201_28_dialog_content = "สิ่งนั้นไม่สำคัญอีกต่อไป ไม่มีทางหลีกเลี่ยงการต่อสู้ครั้งนี้แล้ว",
  ui_story_5081_50811201_29_dialog_content = "เจ้าหน้าที่วิทยาการกรอนรู คุณรู้ไหมว่าการขาดหายของคุณไปจากอิลลูมินาได้ทำให้เกิดความวุ่นวายเพียบ?",
  ui_story_5081_50811201_30_dialog_content = "โอย, วุ่นวายชะมัด...",
  ui_story_5081_50811201_31_dialog_content = "อย่าบอกฉันว่าอาวุธป้องกันอิคลิพไซท์รุ่นล่าสุดเริ่มทำงานผิดพลาดอีกแล้ว! ถ้าเป็นอย่างนั้น ก็ใช้อย่างอื่นซะ!",
  ui_story_5081_50811201_32_dialog_content = "อาวุธเก่าๆของฉันสามารถทำงานได้ดีเพียงพอ!",
  ui_story_5081_50811201_33_dialog_content = "หรือคณะกรรมการยังไม่ได้ทำความสะอาดหลังจากตัวเองหรือ?",
  ui_story_5081_50811201_34_dialog_content = "เสมอๆ การลากยาวการประชุมด้วยคำพูดที่มีความสำคัญต่อตัวเองและโอ้อวด... ทุกคนทิ้งสมองไปที่หน้าต่างเมื่อพวกเขาไปถึงยอดหรืออะไรเช่นนั้นหรือ?",
  ui_story_5081_50811201_35_dialog_content = "หรืออาจจะมีบางคนในห้องแล็บทดลองทะเลาะกันเรื่องโครงการที่ควรจะดำเนินต่อหรือโครงการที่ควรยกเลิกอีกครั้งหรือเปล่า?",
  ui_story_5081_50811201_36_dialog_content = "โครงการใดๆที่ไม่ผ่านการตรวจสอบจะถูกยกเลิกโดยไม่คิดค้น แม้ว่าทั้งหมดที่พวกเขาต้องการก็เพียงการสนับสนุนเพิ่มเติมเล็กน้อย! มันทำให้ฉันโกรธมาก!",
  ui_story_5081_50811201_37_dialog_content = "สภาพจิตใจของเธอ...",
  ui_story_5081_50811201_38_dialog_content = "มันแย่กว่าของอูริเอลอีกนี่หรือเปล่า?",
  ui_story_5081_50811201_39_dialog_content = "แม้ว่าคุณจะไม่สามารถรับผิดชอบทั้งหมดเหล่านั้นได้ แต่ก็ไม่ใช่ข้ออ้างที่จะทิ้งตำแหน่งของคุณโดยไม่ได้รับอนุญาต—",
  ui_story_5081_50811201_40_dialog_content = "ใครบอกว่าฉันไม่ได้รับการอนุมัติ? ฉันได้ยื่นคำขอเวลาพักร้อนแล้ว! และฉันได้อนุมัติมันเอง!",
  ui_story_5081_50811201_41_dialog_content = "ฉันยังไปติดประกาศเวลาที่ฉันหยุดทั้งหมดที่สำนักงานของฉัน! อย่าบอกฉันว่าคุณไม่เห็นพวกเขา!",
  ui_story_5081_50811201_42_dialog_content = "อ๊ากกก, พอแล้ว! ฉันจะไม่ยอมให้ทั้งสองคนขัดขวางเกม Longzhou Tilemaster ของฉัน—",
  ui_story_5081_50811201_43_dialog_content = "ถ้าคุณต้องการให้ฉันกลับไปที่สำนักงาน คุณจะต้องลากศพฉันที่เย็นชาไปที่นั่น!",
  ui_story_5081_50811201_44_dialog_content = "หลงโจว Tilemaster? ฉันคิดว่าฉันเคยได้ยินเกี่ยวกับเกมนี้ มันคล้ายๆ กับมาจง...",
  ui_story_5081_50811201_45_dialog_content = "อ้าว? แต่ฉันคิดว่าคุณกำลังทำงานเกี่ยวกับเกมแฟนตาซีเสร็จสิ้นอยู่นี่นา กรอนรู? ทำไมคุณถึงหยุดเกมนั้นไว้ล่ะครับ?",
  ui_story_5081_50811201_46_dialog_content = "ฮืม... ไม่ว่าแล้ว! ไม่มีใครได้รบกวนฉันตอนนี้นะ คุณได้ยินไหม? ไม่มีใครเลย!",
  ui_story_5081_50811201_47_dialog_content = "เริ่มเกมของกรอนรูกันเถอะ!",
  ui_story_5081_50811201_48_dialog_content = "...ฉันรู้ว่ามันจะลงเอยแบบนี้",
  ui_story_5081_50811201_49_dialog_content = "เอามันสิ, เพง-เพง!",
