  ui_story_5081_50811300_10_dialog_content = "\"ยุติธรรม\"? คำนั้นไม่มีอยู่ที่ไหนในแอสตราเลย!",
  ui_story_5081_50811300_11_dialog_content = "โกงเป็นส่วนหนึ่งของเกมของกรอนรู! ถ้าคุณไม่ชอบ ก็ออกไปเถอะ!",
  ui_story_5081_50811300_12_dialog_content = "ฮ่าาาาาาาห์—",
  ui_story_5081_50811300_13_dialog_content = "เดี๋ยวนะ... เธอจริง ๆ ใช้โปรแกรมโกงเหรอ?",
  ui_story_5081_50811300_14_dialog_content = "ทำไมห้องทั้งหลังถึงสั่นสะเทือนเหมือนกำลังจะระเบิดตัวเองล่ะ?",
  ui_story_5081_50811300_15_dialog_content = "เธอใช้โกงเกมมากเกินไปจนทำให้เครื่องเกมโหลดหนักเกินไปหรือเปล่า?",
  ui_story_5081_50811300_16_dialog_content = "ทุกชิ้นของอุปกรณ์ในห้องนี้เชื่อมต่อกัน...",
